<?php
namespace App\Http\Controllers;
use App\Models\Producto; use App\Services\ValidacionBiologicaService; use Illuminate\Http\Request; use Inertia\Inertia;
class CatalogoController { public function index(Request $r){$q=Producto::query()->when($r->search,fn($b,$v)=>$b->where(fn($x)=>$x->where('nombre','ilike','%'.$v.'%')->orWhere('descripcion','ilike','%'.$v.'%')->orWhere('marca','ilike','%'.$v.'%')))->when($r->tipo_agua,fn($b,$v)=>$b->where('tipo_agua',$v))->when($r->marca,fn($b,$v)=>$b->where('marca',$v))->when($r->precio_min,fn($b,$v)=>$b->where('precio','>=',$v))->when($r->precio_max,fn($b,$v)=>$b->where('precio','<=',$v))->paginate(24)->withQueryString();return Inertia::render('Catalogo/Index',['productos'=>$q,'filtros'=>$r->only(['search','tipo_agua','marca','precio_min','precio_max'])]);} public function show(Producto $producto){return Inertia::render('Catalogo/Show',['producto'=>$producto]);} public function compatibility(Request $r,ValidacionBiologicaService $service){$v=$r->validate(['producto_id'=>'required|exists:productos,id','cart'=>'array','cart.*'=>'integer|distinct|exists:productos,id']);$product=Producto::findOrFail($v['producto_id']);$others=Producto::whereIn('id',$v['cart']??[])->get();return response()->json(['incompatibles'=>$product->es_ser_vivo?$service->incompatibles($product,$others):[]]);} }
